"use client";
import { useRef } from "react";
import {
  useScrollMotion,
  scrollStage,
  type ScrollMotionProps,
  type ScrollItem,
} from "./scroll-shared";
export interface AnimatedGridProps extends ScrollMotionProps {
  items: readonly ScrollItem[];
  columns?: number;
  gap?: number;
  distance?: number;
  variant?: "alternating" | "wave" | "fan";
  aspectRatio?: number;
}
export function AnimatedGrid({
  items,
  columns = 5,
  gap = 14,
  distance = 160,
  variant = "alternating",
  aspectRatio = 0.75,
  ...props
}: AnimatedGridProps) {
  const root = useRef<HTMLDivElement>(null),
    count = Math.max(1, Math.min(12, Math.floor(columns))),
    groups = Array.from({ length: count }, (_, i) => items.filter((_, j) => j % count === i));
  useScrollMotion(
    root,
    props,
    ({ progress: p, reduced, width }) => {
      const cols = root.current!.querySelectorAll<HTMLElement>(":scope > [data-scroll-column]");
      root.current!.style.setProperty("--scroll-grid-gap", `${Math.min(gap, width * 0.04)}px`);
      cols.forEach((el, i) => {
        const speed =
            variant === "wave" ? Math.cos((i / (count - 1 || 1)) * Math.PI * 2) : i % 2 ? 1 : -1,
          y = reduced ? 0 : (p - 0.5) * distance * speed,
          angle = reduced || variant !== "fan" ? 0 : (i - (count - 1) / 2) * (1 - p) * 8;
        el.style.transform = `translateY(${y}px) rotate(${angle}deg)`;
      });
    },
    `${count}:${gap}:${distance}:${variant}:${items.map((x) => x.id).join(",")}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="animated-grid"
      className={props.className}
      style={{
        ...scrollStage,
        display: "grid",
        gridTemplateColumns: `repeat(${count},minmax(0,1fr))`,
        alignItems: "center",
        gap,
        ...props.style,
      }}
    >
      {groups.map((group, i) => (
        <div
          key={i}
          data-scroll-column={i}
          style={{
            display: "grid",
            gap: "var(--scroll-grid-gap,14px)",
            transformOrigin: "50% 100%",
          }}
        >
          {group.map((item) => (
            <div
              data-scroll-unit={item.id}
              key={item.id}
              className={item.className}
              style={{
                aspectRatio,
                minWidth: 0,
                borderRadius: 7,
                overflow: "hidden",
                ...item.style,
              }}
            >
              {item.content}
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}
